{
  "technical_and_design_decisions": [
    "AWS EC2 / Packer automation scripts will be used to create repeatable AMIs for Kafka performance testing and Windows CI build nodes.",
    "Load generator source and receiving sink modules will be built as standard Spring XD modules using Spring Integration messaging channels.",
    "Kafka source offset management will be refactored using Apache Kafka consumer client APIs to support explicit offset seeking and batch fetch optimization.",
    "Static GitHub Pages (gh-pages) will be built using standard Markdown/Jekyll structure to publish tutorials, benchmarks, and reference architectures.",
    "Lattice/Diego POC will focus on defining SPI interfaces for container execution in the Spring XD runtime environment."
  ],
  "assumptions": [
    "AWS account access and privileges are available for launching and snapshotting EC2 instances.",
    "A CI server (such as Jenkins or Bamboo) is already operational and capable of registering Windows build slaves.",
    "Kafka brokers and test infrastructure are accessible for running performance benchmarks.",
    "A single full-stack Java/Spring developer will perform all development, infrastructure setup, testing, and documentation."
  ],
  "activities": [
    {
      "activity_id": "ACT-1",
      "activity_name": "Create EC2 AMI for Kafka Perf Tests (U1)",
      "activity_description": "Provision and configure an AWS EC2 AMI pre-packaged with Java, Kafka, benchmarking tools, and OS optimizations necessary for running performance tests.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "ACT-2",
      "activity_name": "Develop Load Generator Source Module (U2)",
      "activity_description": "Implement a Spring XD source module capable of generating configurable throughput load (rates, payload sizes, multi-threading) for perf testing.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "ACT-3",
      "activity_name": "Develop Load Receiving Sink Module (U3)",
      "activity_description": "Implement a Spring XD sink module to consume streams and calculate metrics such as received messages per second, latency, and total throughput.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "ACT-4",
      "activity_name": "Schedule Windows CI Builds and Isolate Test Failures (U4)",
      "activity_description": "Set up CI builds on Windows nodes, experiment with Windows AMIs, isolate failing runtime tests, and configure stable build pipelines.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "ACT-5",
      "activity_name": "Fix Kafka Source Offset Management (U5)",
      "activity_description": "Refactor offset commit and fetch logic in the Kafka source module to allow efficient fetch operations starting from specific offsets.",
      "most_likely_effort": 18
    },
    {
      "activity_id": "ACT-6",
      "activity_name": "Measure and Characterize Simple Stream Performance (U6)",
      "activity_description": "Construct baseline performance streams using the load generator source and sink modules, execute test runs, collect data, and document throughput metrics.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "ACT-7",
      "activity_name": "Create static gh_pages Site for Collateral (U7)",
      "activity_description": "Set up and structure the gh_pages branch with documentation, code samples, tutorials, benchmark results, and reference architecture diagrams.",
      "most_likely_effort": 14
    },
    {
      "activity_id": "ACT-8",
      "activity_name": "Lattice/Diego POC for Pluggable SPI (U8)",
      "activity_description": "Investigate Lattice/Diego runtime architecture, prototype a pluggable runtime SPI in Spring XD, and document scope, risks, and design options.",
      "most_likely_effort": 30
    }
  ],
  "reported_total": {
    "most_likely_effort": 150
  }
}

